#!/usr/bin/env node
// Generates src/api/schema.ts, the TypeScript types of the REST API, from contracts/openapi.yaml.
//
//   node scripts/gen-api.mjs           writes src/api/schema.ts      (npm run gen:api)
//   node scripts/gen-api.mjs --check   exits 1 if it's out of date   (npm run check:api)
//
// The generated file is committed, so the UI builds without the contracts folder. Run this after
// every change to openapi.yaml; `npm run check` fails until you do.

import { readFileSync, writeFileSync } from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';

const contract = new URL('../../contracts/openapi.yaml', import.meta.url);
const target = new URL('../src/api/schema.ts', import.meta.url);

const header = `// Generated by scripts/gen-api.mjs from contracts/openapi.yaml with openapi-typescript.
// Don't edit: change the contract, then run npm run gen:api.
/* eslint-disable */
`;

const ast = await openapiTS(contract);
const output = header + '\n' + astToString(ast);

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    // A missing file counts as out of date.
  }
  if (current !== output) {
    console.error('gen-api: src/api/schema.ts is out of date. Run npm run gen:api');
    process.exit(1);
  }
  console.log('gen-api: src/api/schema.ts is up to date.');
} else {
  writeFileSync(target, output);
  console.log('gen-api: wrote src/api/schema.ts');
}
